begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('00000000-0000-0000-0000-000000000181','durations@example.invalid','{"requested_username":"DurationOwner"}');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000181","role":"authenticated"}',true);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000181',0,'Duration rivalry','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[1,60]}',array['Alpha','Beta','Gamma','Delta']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000182',0,'Legacy queued rivalry','','food-drink','donut','public','{"mode":"per-round","roundHours":["1","2"]}',array['Alpha','Beta','Gamma','Delta']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000183',0,'Private status rivalry','','food-drink','donut','private','{"mode":"manual"}',array['Alpha','Beta']);
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000182',1)$$,'22023',null,'new legacy submissions require reopening in duration editor');
select public.save_bracket_draft('10000000-0000-0000-0000-000000000184',0,'Invalid duration rivalry','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[0]}',array['Alpha','Beta']);
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000184',1)$$,'22023',null,'zero duration cannot submit');
update public.brackets set schedule_preferences='{"mode":"per-round","roundMinutes":[44640]}' where id='10000000-0000-0000-0000-000000000184';
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000184',1)$$,'22023',null,'duration above maximum cannot submit');
update public.brackets set schedule_preferences='{"mode":"per-round","roundMinutes":[1.5]}' where id='10000000-0000-0000-0000-000000000184';
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000184',1)$$,'22023',null,'fractional minutes cannot submit');
update public.brackets set schedule_preferences='{"mode":"per-round","roundMinutes":["60"]}' where id='10000000-0000-0000-0000-000000000184';
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000184',1)$$,'22023',null,'duration values must be JSON numbers');
update public.brackets set schedule_preferences='{"mode":"per-round","roundMinutes":[44639]}' where id='10000000-0000-0000-0000-000000000184';
select lives_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000184',1)$$,'maximum duration can submit');
select public.submit_bracket('10000000-0000-0000-0000-000000000181',1);
select public.submit_bracket('10000000-0000-0000-0000-000000000183',1);
-- A legacy bracket already accepted before migration keeps its schedule.
update public.brackets set status='pending_review' where id='10000000-0000-0000-0000-000000000182';
insert into app_private.bracket_review_queue values('10000000-0000-0000-0000-000000000182',clock_timestamp()-interval '1 second');
update app_private.bracket_review_queue set not_before=clock_timestamp()-interval '1 second';
select app_private.process_competitions();
select is((select ends_at-starts_at from public.bracket_rounds where bracket_id='10000000-0000-0000-0000-000000000181' and round_index=0),interval '1 minute','first round gets full duration');
select is((public.get_competition('10000000-0000-0000-0000-000000000181')->>'durationBased')::boolean,true,'snapshot identifies duration schedules');
select throws_ok($$update public.bracket_rounds set ends_at=ends_at+interval '1 day' where bracket_id='10000000-0000-0000-0000-000000000181' and round_index=0$$,'55000',null,'open duration deadlines remain immutable');
-- Simulate worker downtime exceeding projected deadlines.
alter table public.bracket_rounds disable trigger guard_round_structure;
update public.bracket_rounds set starts_at=starts_at-interval '10 days',ends_at=ends_at-interval '10 days' where bracket_id in ('10000000-0000-0000-0000-000000000181','10000000-0000-0000-0000-000000000182');
alter table public.bracket_rounds enable trigger guard_round_structure;
select app_private.process_competitions();
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000181'),'active','duration bracket does not skip later rounds after downtime');
select is((select ends_at-starts_at from public.bracket_rounds where bracket_id='10000000-0000-0000-0000-000000000181' and round_index=1),interval '1 hour','next round receives its full hour at actual opening');
select ok((select ends_at>clock_timestamp()+interval '59 minutes' from public.bracket_rounds where bracket_id='10000000-0000-0000-0000-000000000181' and round_index=1),'next deadline is future despite delayed closure');
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000182'),'completed','legacy fixed deadlines retain catch-up behavior');
select set_config('request.jwt.claims','{}',true);
set local role anon;
select is(public.get_competition_status('10000000-0000-0000-0000-000000000183'),null::jsonb,'anonymous status cannot expose private brackets');
select is(public.get_competition_status('10000000-0000-0000-0000-000000000181')->>'status','active','public status is available');
select is((select count(*) from jsonb_object_keys(public.get_competition_status('10000000-0000-0000-0000-000000000181'))),4::bigint,'status exposes only state, round, clock and deadline');
reset role;
select is((select count(*) from app_private.competition_worker_errors),0::bigint,'duration processing leaves no worker errors');
select * from finish();
rollback;
